package pt.ipp.isep.dei.pi25_26.g093.app.domain;

/**
 * Represents an individual item (product) placed inside a trolley.
 * <p>
 * Each item corresponds to an allocation entry generated by the USEI02 module.
 * It stores the order reference, SKU, quantity, total weight, and its warehouse location (aisle and bay).
 */
public class TrolleyItem {

    private final String orderId;
    private final String sku;
    private final int qty;
    private final double weight; // total weight (qty * unitWeight)
    private final int aisle;
    private final int bay;

    /**
     * Constructs a new TrolleyItem with the specified details.
     *
     * @param orderId the ID of the order this item belongs to
     * @param sku the SKU (Stock Keeping Unit) identifier of the product
     * @param qty the quantity of this item in the order
     * @param weight the total weight of this item (quantity × unit weight)
     * @param aisle the aisle number where this item is located
     * @param bay the bay number where this item is located
     */
    public TrolleyItem(String orderId, String sku, int qty, double weight, int aisle, int bay) {
        this.orderId = orderId;
        this.sku = sku;
        this.qty = qty;
        this.weight = weight;
        this.aisle = aisle;
        this.bay = bay;
    }

    public String getOrderId() { return orderId; }
    public String getSku() { return sku; }
    public int getQty() { return qty; }
    public double getWeight() { return weight; }
    public int getAisle() { return aisle; }
    public int getBay() { return bay; }

    /**
     * Returns a human-readable description of this trolley item,
     * including order, SKU, quantity, total weight, and location.
     */
    @Override
    public String toString() {
        return String.format("Order %s | SKU %s | Qty %d | %.2f kg | (Aisle %d, Bay %d)",
                orderId, sku, qty, weight, aisle, bay);
    }
}


